INSERT INTO `bfs_state` VALUES (1,'{\"settings\":{\"company\":\"Barrier Builders\",\"tagline\":\"The fence that holds.\",\"domain\":\"barrierfencing.co.zw\",\"email\":\"info@barrierfencing.co.zw\",\"salesEmail\":\"sales@barrierfencing.co.zw\",\"phone\":\"+263 77 456 7890\",\"whatsapp\":\"263774567890\",\"address\":\"42 Coventry Road, Workington, Harare, Zimbabwe\",\"hours\":\"Mon–Fri 07:30–17:00 · Sat 08:00–13:00\",\"vatRate\":0.15,\"currency\":\"USD\",\"quoteValidityDays\":14,\"adminUser\":\"admin\",\"adminPass\":\"Barrier@2026\",\"vatNumber\":\"VAT 10001234\",\"bank\":\"Stanbic Bank — Barrier Builders — Acc 000000000000\"},\"products\":[{\"id\":\"p1\",\"slug\":\"diamond-mesh\",\"name\":\"Diamond Mesh\",\"category\":\"Residential\",\"unit\":\"roll\",\"short\":\"Versatile hot-dip galvanized chain-link for homes, schools and commercial plots.\",\"description\":\"Our most requested fence. Woven diamond mesh in 2.0–4.0 mm gauges, apertures 50 / 63 / 75 mm, heights from 0.9 m to 2.4 m. Hot-dip galvanized for 15+ years of corrosion resistance in Zimbabwean conditions.\",\"specs\":{\"gauge\":\"2.0–4.0 mm\",\"aperture\":\"50 / 63 / 75 mm\",\"heights\":\"0.9–2.4 m\",\"coating\":\"Hot-dip galvanized, min 80 µm\"},\"pricePerM\":12,\"rollPrice\":120,\"rollMetres\":30,\"postPrice\":8,\"topWirePerM\":0.8,\"gatePrice\":180,\"installPerM\":3.5,\"concretePerPost\":4,\"stock\":420,\"stockUnit\":\"rolls\",\"featured\":true,\"image\":\"assets/img/diamond-mesh.jpg\",\"keywords\":[\"diamond\",\"chain\",\"residential\",\"home\",\"house\",\"plot\",\"school\",\"boundary\"]},{\"id\":\"p2\",\"slug\":\"game-fence\",\"name\":\"Game Fence\",\"category\":\"Agricultural\",\"unit\":\"roll\",\"short\":\"Heavy-duty knotted fence for wildlife ranches, conservancies and large farms.\",\"description\":\"Knotted high-tensile game fence designed to contain large wildlife including kudu, eland and buffalo. Heights 1.2–2.4 m. Built for Matabeleland and Mashonaland ranch conditions.\",\"specs\":{\"gauge\":\"2.0–3.15 mm\",\"joint\":\"Knotted, impact-resistant\",\"heights\":\"1.2–2.4 m\",\"coating\":\"Hot-dip galvanized\"},\"pricePerM\":18,\"rollPrice\":280,\"rollMetres\":50,\"postPrice\":12,\"topWirePerM\":1.1,\"gatePrice\":220,\"installPerM\":4,\"concretePerPost\":5,\"stock\":86,\"stockUnit\":\"rolls\",\"featured\":true,\"image\":\"assets/img/game-fence.jpg\",\"keywords\":[\"game\",\"wildlife\",\"farm\",\"hectare\",\"ranch\",\"livestock\",\"conservancy\"]},{\"id\":\"p3\",\"slug\":\"barbed-wire\",\"name\":\"Barbed Wire\",\"category\":\"Security\",\"unit\":\"roll\",\"short\":\"High-tensile 2.5 mm barbed wire for farm boundaries and perimeter topping.\",\"description\":\"12.5 gauge galvanized barbed wire, barb spacing 75–100 mm, 100 m and 200 m rolls. Used as a standalone farm fence or as a top strand on diamond mesh.\",\"specs\":{\"gauge\":\"2.5 mm (12.5g)\",\"barb\":\"75–100 mm\",\"rolls\":\"100 m / 200 m\",\"coating\":\"Hot-dip galvanized\"},\"pricePerM\":1.9,\"rollPrice\":45,\"rollMetres\":100,\"postPrice\":8,\"topWirePerM\":0.6,\"gatePrice\":160,\"installPerM\":2.5,\"concretePerPost\":4,\"stock\":610,\"stockUnit\":\"rolls\",\"featured\":true,\"image\":\"assets/img/barbed-wire.jpg\",\"keywords\":[\"barbed\",\"perimeter\",\"farm\",\"budget\",\"top wire\"]},{\"id\":\"p4\",\"slug\":\"razor-wire\",\"name\":\"Razor Wire\",\"category\":\"Security\",\"unit\":\"coil\",\"short\":\"Concertina BTO-22 razor coils for high-risk commercial and institutional sites.\",\"description\":\"Maximum-security concertina razor wire in 450, 600 and 900 mm coil diameters. Hot-dip galvanized BTO-22 blades for prisons, mines, warehouses and wall-top upgrades.\",\"specs\":{\"blade\":\"BTO-22\",\"coils\":\"450 / 600 / 900 mm\",\"coating\":\"Hot-dip galvanized steel\"},\"pricePerM\":6.5,\"rollPrice\":95,\"rollMetres\":50,\"postPrice\":14,\"topWirePerM\":1.4,\"gatePrice\":260,\"installPerM\":4.5,\"concretePerPost\":5,\"stock\":140,\"stockUnit\":\"coils\",\"featured\":true,\"image\":\"assets/img/razor-wire.jpg\",\"keywords\":[\"razor\",\"security\",\"prison\",\"commercial\",\"industrial\",\"warehouse\",\"high\"]},{\"id\":\"p5\",\"slug\":\"clear-view\",\"name\":\"Clear View Fence\",\"category\":\"Security\",\"unit\":\"panel\",\"short\":\"Anti-climb welded mesh with unobstructed visibility for estates, schools and embassies.\",\"description\":\"4.0 mm welded mesh, 76.2 × 12.7 mm aperture, anti-climb and anti-cut. Optional spike-top. Powder-coated forest green or galvanized finish.\",\"specs\":{\"wire\":\"4.0 mm\",\"aperture\":\"76.2 × 12.7 mm\",\"features\":\"Anti-climb, anti-cut, spike-top option\"},\"pricePerM\":38,\"rollPrice\":190,\"rollMetres\":3,\"postPrice\":22,\"topWirePerM\":1.6,\"gatePrice\":420,\"installPerM\":8,\"concretePerPost\":8,\"stock\":74,\"stockUnit\":\"panels\",\"featured\":true,\"image\":\"assets/img/clear-view.jpg\",\"keywords\":[\"clear\",\"view\",\"embassy\",\"school\",\"estate\",\"anti-climb\"]},{\"id\":\"p6\",\"slug\":\"palisade\",\"name\":\"Palisade Fencing\",\"category\":\"Security\",\"unit\":\"m\",\"short\":\"Steel palisade pales for industrial yards, schools and high-security compounds.\",\"description\":\"Locally fabricated W-section or D-section pales, powder-coated dark green or galvanized. A strong visual and physical deterrent.\",\"specs\":{\"pale\":\"W or D section\",\"heights\":\"1.8–2.4 m\",\"finish\":\"Galvanized / powder coat green\"},\"pricePerM\":55,\"rollPrice\":55,\"rollMetres\":1,\"postPrice\":28,\"topWirePerM\":0,\"gatePrice\":480,\"installPerM\":12,\"concretePerPost\":10,\"stock\":210,\"stockUnit\":\"metres\",\"featured\":true,\"image\":\"assets/img/palisade.jpg\",\"keywords\":[\"palisade\",\"industrial\",\"school\",\"compound\",\"steel\"]},{\"id\":\"p7\",\"slug\":\"welded-mesh\",\"name\":\"Welded Mesh\",\"category\":\"Industrial\",\"unit\":\"panel\",\"short\":\"Rigid welded panels for enclosures, reinforcement and industrial fencing.\",\"description\":\"Square and rectangular welded mesh in multiple gauges. Used for cages, machine guards, slab reinforcement and light security fencing.\",\"specs\":{\"aperture\":\"50 × 50 mm and custom\",\"gauge\":\"2.5–4.0 mm\"},\"pricePerM\":14,\"rollPrice\":70,\"rollMetres\":6,\"postPrice\":10,\"topWirePerM\":0.7,\"gatePrice\":200,\"installPerM\":3.2,\"concretePerPost\":4,\"stock\":188,\"stockUnit\":\"panels\",\"featured\":false,\"image\":\"assets/img/welded-mesh.jpg\",\"keywords\":[\"welded\",\"panel\",\"industrial\",\"cage\"]},{\"id\":\"p8\",\"slug\":\"chicken-mesh\",\"name\":\"Chicken Mesh\",\"category\":\"Agricultural\",\"unit\":\"roll\",\"short\":\"Lightweight hexagonal netting for poultry runs, gardens and small animals.\",\"description\":\"0.7–1.0 mm hex netting, 25 mm and 50 mm apertures, heights 0.6–1.8 m. Galvanized against rust in the rainy season.\",\"specs\":{\"gauge\":\"0.7–1.0 mm\",\"aperture\":\"25 / 50 mm\",\"heights\":\"0.6–1.8 m\"},\"pricePerM\":4.2,\"rollPrice\":32,\"rollMetres\":30,\"postPrice\":6,\"topWirePerM\":0.5,\"gatePrice\":140,\"installPerM\":2,\"concretePerPost\":3,\"stock\":260,\"stockUnit\":\"rolls\",\"featured\":false,\"image\":\"assets/img/chicken-mesh.jpg\",\"keywords\":[\"chicken\",\"poultry\",\"birds\",\"coop\",\"garden\",\"pet\"]},{\"id\":\"p9\",\"slug\":\"field-fence\",\"name\":\"Field Fence\",\"category\":\"Agricultural\",\"unit\":\"roll\",\"short\":\"Woven field fence for cattle, goats and crop protection on rural properties.\",\"description\":\"Graduated mesh field fence that keeps livestock in and predators out. Ideal for mixed farming operations.\",\"specs\":{\"type\":\"Hinged joint / woven\",\"heights\":\"1.0–1.5 m\",\"rolls\":\"50 m\"},\"pricePerM\":8.5,\"rollPrice\":180,\"rollMetres\":50,\"postPrice\":10,\"topWirePerM\":0.9,\"gatePrice\":200,\"installPerM\":3,\"concretePerPost\":4,\"stock\":95,\"stockUnit\":\"rolls\",\"featured\":false,\"image\":\"assets/img/field-fence.jpg\",\"keywords\":[\"field\",\"cattle\",\"goats\",\"crop\",\"rural\",\"livestock\"]},{\"id\":\"p10\",\"slug\":\"electric-fence\",\"name\":\"Electric Fence\",\"category\":\"Security\",\"unit\":\"kit\",\"short\":\"Wall-top or full-height electric fence systems with energizer and siren.\",\"description\":\"High-voltage pulsed deterrent for residential and commercial walls. Kits include energizer, insulators, HT wire and battery backup options.\",\"specs\":{\"type\":\"Wall-top or full height\",\"kit\":\"Energizer, HT wire, insulators\"},\"pricePerM\":9.5,\"rollPrice\":95,\"rollMetres\":20,\"postPrice\":0,\"topWirePerM\":0,\"gatePrice\":0,\"installPerM\":7,\"concretePerPost\":0,\"stock\":54,\"stockUnit\":\"kits\",\"featured\":false,\"image\":\"assets/img/electric-fence.jpg\",\"keywords\":[\"electric\",\"energizer\",\"wall top\",\"alarm\"]},{\"id\":\"p11\",\"slug\":\"gates\",\"name\":\"Gates\",\"category\":\"Access\",\"unit\":\"set\",\"short\":\"Custom sliding, swing and pedestrian gates fabricated to opening width.\",\"description\":\"Hot-dip galvanized steel gates: sliding, double-leaf and pedestrian. Mesh, palisade or clear-view infill. Automation on request.\",\"specs\":{\"types\":\"Sliding / swing / pedestrian\",\"finish\":\"Galvanized or powder coat\"},\"pricePerM\":180,\"rollPrice\":180,\"rollMetres\":1,\"postPrice\":0,\"topWirePerM\":0,\"gatePrice\":180,\"installPerM\":40,\"concretePerPost\":0,\"stock\":22,\"stockUnit\":\"sets\",\"featured\":false,\"image\":\"assets/img/gate.jpg\",\"keywords\":[\"gate\",\"entrance\",\"access\",\"sliding\"]},{\"id\":\"p12\",\"slug\":\"posts\",\"name\":\"Fence Posts & Standards\",\"category\":\"Accessories\",\"unit\":\"pc\",\"short\":\"Galvanized line posts, corner posts, Y-posts and straining assemblies.\",\"description\":\"Round tube, Y-post and corner assemblies from 1.2 m to 2.4 m. Sold with stay wires and fittings.\",\"specs\":{\"heights\":\"1.2–2.4 m\",\"types\":\"Line, corner, Y-post\"},\"pricePerM\":8,\"rollPrice\":8,\"rollMetres\":1,\"postPrice\":8,\"topWirePerM\":0,\"gatePrice\":0,\"installPerM\":0,\"concretePerPost\":4,\"stock\":980,\"stockUnit